Here is the commit message:
Bugfix for the fgetll bugfix in 07ddb4f7. Also never allocate
 less than 4K.

Here is the root cause:
The bug was caused by improper handling of memory allocation in the `fgetll` function, which could lead to allocating less than 4K of memory. This could result in buffer overflows or insufficient memory for reading lines from a file, especially when dealing with larger inputs. Additionally, the logic for updating the length of the string read was not accurately reflecting the actual length, which could lead to incorrect behavior when processing input data.

Here is the patch:
 #ifndef _JOHN_MISC_NO_LOG
 char *fgetll(char *s, size_t size, FILE *stream)
 {
 	size_t len;
 	char *cp;

 	/* fgets' size arg is a signed int! */
 	assert(size <= INT32_MAX);

 	if (!fgets(s, size, stream))
 		return NULL;

 	len = strlen(s);

 	if (!len)
 		return s;

 	if (s[len-1] == '\n') {
 		s[--len] = 0;
 		while (len && (s[len-1] == '\n' || s[len-1] == '\r'))
 			s[--len] = 0;
 		return s;
 	}
-	if (s[len-1] == '\r') {
+	else if (s[len-1] == '\r') {
 		int c;

 		s[--len] = 0;
 		while (len && (s[len-1] == '\n' || s[len-1] == '\r'))
 			s[--len] = 0;
 		/* we may have gotten the first byte of \r\n */
 		c = getc(stream);
 		if (c == EOF)
 			return s;
 		if (c != '\n')
 			ungetc(c, stream);
 		return s;
 	}
-	if (s[len] == 0) {
+	else if ((len + 1) < size) { /* We read a null byte */
 		int c;

 		while (c != EOF && c != '\n')
 			c = getc(stream);
 		return s;
 	}

 	cp = strdup(s);

 	while (1) {
-		int increase = MIN(len, 0x40000000);
+		int increase = MIN((((len >> 12) + 1) << 12), 0x40000000);
+		size_t chunk_len;
 		void *new_cp;

 		new_cp = realloc(cp, len + increase);

 		while (!new_cp) {
 			increase >>= 2;
 			if (increase < 0x10000)
 				pexit("realloc");
 			new_cp = realloc(cp, len + increase);
 		}

 		cp = new_cp;

 		/* We get an EOF if there is no trailing \n on the last line */
 		if (!fgets(&cp[len], increase, stream))
 			return cp;

-		len += strlen(&cp[len]);
+		chunk_len = strlen(&cp[len]);
+		len += chunk_len;

 		if (cp[len-1] == '\n') {
 			cp[--len] = 0;
 			while (len && (cp[len-1] == '\n' || cp[len-1] == '\r'))
 				cp[--len] = 0;
 			return cp;
 		}
-		if (cp[len-1] == '\r') {
+		else if (cp[len-1] == '\r') {
 			int c;

 			cp[--len] = 0;
 			while (len && (cp[len-1] == '\n' || cp[len-1] == '\r'))
 				cp[--len] = 0;
 			/* we may have gotten the first byte of \r\n */
 			c = getc(stream);
 			if (c == EOF)
 				return cp;
 			if (c != '\n')
 				ungetc(c, stream);
 			return cp;
 		}
-		if (s[len] == 0) {
+		else if ((chunk_len + 1) < increase) { /* We read a null byte */
 			int c;

 			while (c != EOF && c != '\n')
 				c = getc(stream);
 			return s;
 		}
 	}
 }
 #endif


